1	// The constructor keeps a public named param (`localAuthentication`)
2	// distinct from the private field it initializes, matching
3	// `session_repository_impl.dart`'s documented convention.
4	// ignore_for_file: prefer_initializing_formals
5	import 'dart:async';
6	
7	import 'package:fpdart/fpdart.dart';
8	import 'package:flutter/widgets.dart';
9	import 'package:flutter_secure_storage/flutter_secure_storage.dart';
10	import 'package:local_auth/local_auth.dart';
11	
12	import '../../../../core/failure/failure.dart';
13	import '../../domain/entities/vault_status.dart';
14	import '../../domain/repositories/vault_repository.dart';
15	import '../../domain/vault_idle_timeout.dart';
16	
17	/// Owns the one broadcast [VaultStatus] stream the epic's AD-14 seam
18	/// requires. Covers the I/O matrix (spec-2-1 + spec-2-2 + spec-2-3):
19	/// - biometrics succeed -> [VaultStatus.unlocked] emitted, `Right(unit)`.
20	/// - biometrics fail/cancelled/unavailable (`authenticate()` returns
21	///   `false`, or throws `LocalAuthException`, including any OS lockout) ->
22	///   status stays [VaultStatus.locked], `Left(Failure.
23	///   malformedResponse(...))` — every one of those cases routes the caller
24	///   to [submitPin] next (spec-2-2), with no code-specific branch needed
25	///   here since the generic catches below already cover lockout.
26	/// - [submitPin], no PIN stored yet -> stores it, [VaultStatus.unlocked]
27	///   emitted, `Right(unit)`.
28	/// - [submitPin], stored PIN matches -> [VaultStatus.unlocked] emitted,
29	///   `Right(unit)`.
30	/// - [submitPin], stored PIN mismatch -> status stays locked, `Left(Failure.
31	///   malformedResponse(...))`, always retryable (no attempt cap).
32	/// - spec-2-3: backgrounded (`AppLifecycleState.paused`) for >= 5 minutes
33	///   while [VaultStatus.unlocked], then resumed -> [VaultStatus.locked]
34	///   emitted via [didChangeAppLifecycleState]; below that threshold, or
35	///   while already locked, no emission at all.
36	///
37	/// Zero network calls anywhere in this class (Boundaries: "Vault makes zero
38	/// network calls") and never produces [Failure.authInvalid] (Boundaries:
39	/// reserved for password login) — every failure branch below maps only to
40	/// [Failure.malformedResponse]. The PIN is compared as a plain string
41	/// (Design Notes: `flutter_secure_storage` already encrypts at rest;
42	/// `package:crypto` isn't a pinned dependency) stored under [_pinStorageKey]
43	/// via the same [FlutterSecureStorage] instance
44	/// `SecureStorageAccessTokenProvider` uses for the access/refresh tokens.
45	class VaultRepositoryImpl
46	    with WidgetsBindingObserver
47	    implements VaultRepository {
48	  VaultRepositoryImpl({
49	    required LocalAuthentication localAuthentication,
50	    required FlutterSecureStorage secureStorage,
51	    DateTime Function() now = DateTime.now,
52	  }) : _localAuthentication = localAuthentication,
53	       _secureStorage = secureStorage,
54	       _now = now {
55	    // Story 2.3 — observes app-lifecycle transitions directly so idle
56	    // re-lock works with zero DI changes and zero new VaultRepository
57	    // methods. Removed in dispose() below. Safe only because
58	    // `WidgetsFlutterBinding.ensureInitialized()` (or an equivalent, e.g.
59	    // `TestWidgetsFlutterBinding.ensureInitialized()` in tests) must
60	    // already have run before this constructor executes — true today
61	    // because `get_it` constructs this lazily, well after `main()`'s own
62	    // binding initialization.
63	    //
64	    // Review finding: `WidgetsBinding.instance` itself throws an opaque
65	    // Flutter-internal assertion if no binding exists yet — caught here and
66	    // rethrown with a message that names the actual root cause, so any
67	    // future call site that breaks this ordering fails clearly instead of
68	    // opaquely.
69	    try {
70	      WidgetsBinding.instance.addObserver(this);
71	    } on FlutterError catch (error) {
72	      throw StateError(
73	        'VaultRepositoryImpl requires WidgetsFlutterBinding.ensureInitialized() '
74	        '(or TestWidgetsFlutterBinding.ensureInitialized() in tests) to run '
75	        'before construction. Original error: $error',
76	      );
77	    }
78	  }
79	
80	  static const _pinStorageKey = 'vault_pin';
81	
82	  final LocalAuthentication _localAuthentication;
83	  final FlutterSecureStorage _secureStorage;
84	  final DateTime Function() _now;
85	  final StreamController<VaultStatus> _statusController =
86	      StreamController<VaultStatus>.broadcast();
87	
88	  /// Incremented at the start of every [submitPin] call. Review finding:
89	  /// the UI's own `.timeout()` only stops it from *waiting* — the call
90	  /// here keeps running — so a user-triggered retry after that UI timeout
91	  /// could otherwise race a still-in-flight earlier call against the same
92	  /// storage key, or let its stale result emit [VaultStatus.unlocked]
93	  /// behind the newer attempt's back. A call whose captured generation no
94	  /// longer matches this field by the time its [_secureStorage.read]
95	  /// resolves is superseded and must not mutate storage or emit.
96	  int _submitPinGeneration = 0;
97	
98	  /// Set on `AppLifecycleState.paused`, read and cleared on
99	  /// `AppLifecycleState.resumed` (Boundaries: `inactive`/`hidden` are not
100	  /// "backgrounded" on their own — only this pair bounds iOS's actual
101	  /// background/foreground transition). `null` means either the app has
102	  /// never been backgrounded, or the last `paused`->`resumed` cycle already
103	  /// consumed it.
104	  DateTime? _backgroundedAt;
105	
106	  /// The last status emitted. Starts at [VaultStatus.locked] — not
107	  /// nullable, see [VaultStatus]'s own doc — so [currentStatus] is correct
108	  /// synchronously from construction, with no async warm-up step.
109	  VaultStatus _lastStatus = VaultStatus.locked;
110	
111	  @override
112	  VaultStatus get currentStatus => _lastStatus;
113	
114	  @override
115	  Stream<VaultStatus> get statusStream {
116	    // Same `Stream.multi` replay-to-late-listeners rationale as
117	    // `SessionRepositoryImpl.statusStream`: a listener that subscribes
118	    // after construction (but before any [authenticate] call) still
119	    // immediately sees the cached [_lastStatus] ([VaultStatus.locked])
120	    // rather than nothing until the next emission.
121	    return Stream<VaultStatus>.multi((controller) {
122	      controller.add(_lastStatus);
123	      final subscription = _statusController.stream.listen(
124	        controller.add,
125	        onError: controller.addError,
126	        onDone: controller.close,
127	      );
128	      controller.onCancel = subscription.cancel;
129	    }, isBroadcast: true);
130	  }
131	
132	  void _emit(VaultStatus status) {
133	    // Guards against `dispose()` (wired to `get_it`'s `sl.reset()`) racing
134	    // an in-flight `authenticate()` call — mirrors
135	    // `SessionRepositoryImpl._emit`'s own guard.
136	    if (_statusController.isClosed) {
137	      return;
138	    }
139	    if (status == VaultStatus.unlocked) {
140	      // Review finding: without this, a biometric/PIN call that resolves
141	      // while the app is still backgrounded (persistAcrossBackgrounding:
142	      // true covers exactly this) leaves the *original* `_backgroundedAt`
143	      // in place; if `resumed` then arrives >= 5 minutes after that
144	      // original timestamp, the idle check below immediately re-locks the
145	      // vault the instant it was unlocked. Any unlock always starts the
146	      // idle clock fresh instead.
147	      _backgroundedAt = null;
148	    }
149	    _lastStatus = status;
150	    _statusController.add(status);
151	  }
152	
153	  @override
154	  void didChangeAppLifecycleState(AppLifecycleState state) {
155	    // Story 2.3's I/O & Edge-Case Matrix, exactly:
156	    // - `paused` -> record the backgrounded timestamp (only meaningful read
157	    //   on the next `resumed`).
158	    // - `resumed` with no prior `paused` recorded -> no-op (e.g. the very
159	    //   first lifecycle callback ever observed).
160	    // - `resumed` with elapsed time < 5 minutes -> no-op, `currentStatus`
161	    //   stays whatever it was.
162	    // - `resumed` with elapsed time >= 5 minutes AND `currentStatus` is
163	    //   currently `unlocked` -> emit `locked` exactly once; never
164	    //   redundantly if already `locked` (no duplicate emission).
165	    // `inactive`/`hidden` are intentionally ignored (Boundaries) — they
166	    // don't bound the real background/foreground transition on their own.
167	    if (state == AppLifecycleState.paused) {
168	      // Review finding: `??=` (not `=`) — keeps the *earliest* timestamp if
169	      // `paused` ever fires twice before a `resumed` consumes it, so a
170	      // lifecycle quirk can't reset the idle clock to a later start and
171	      // undercount real elapsed background time.
172	      _backgroundedAt ??= _now();
173	      return;
174	    }
175	    if (state == AppLifecycleState.resumed) {
176	      final backgroundedAt = _backgroundedAt;
177	      _backgroundedAt = null;
178	      if (backgroundedAt == null) {
179	        return;
180	      }
181	      final elapsed = _now().difference(backgroundedAt);
182	      if (elapsed >= vaultIdleTimeout && _lastStatus == VaultStatus.unlocked) {
183	        _emit(VaultStatus.locked);
184	      }
185	    }
186	  }
187	
188	  @override
189	  Future<Either<Failure, Unit>> authenticate() async {
190	    try {
191	      // `biometricOnly: true` (Boundaries/Design Notes) — never lets the
192	      // OS's own device-passcode UI satisfy this call, which would bypass
193	      // Cerne's own PIN screen (Story 2.2) entirely.
194	      // `persistAcrossBackgrounding: true` so a backgrounding mid-prompt
195	      // (e.g. an incoming call) retries on foreground instead of failing
196	      // outright.
197	      final success = await _localAuthentication.authenticate(
198	        localizedReason: 'Autentique-se para acessar o Cerne',
199	        biometricOnly: true,
200	        persistAcrossBackgrounding: true,
201	      );
202	      if (success) {
203	        _emit(VaultStatus.unlocked);
204	        return right(unit);
205	      }
206	      // A `false` result (declined/unavailable, no exception) — status
207	      // stays `locked`; never `Failure.authInvalid` (Boundaries: reserved
208	      // for password login).
209	      return left(
210	        const Failure.malformedResponse(
211	          message: 'Biometric authentication was not successful',
212	        ),
213	      );
214	    } on LocalAuthException catch (error) {
215	      // Covers cancellation, no enrolled biometrics, hardware unavailable,
216	      // etc. (RNF09: never let a platform exception escape unmapped).
217	      return left(Failure.malformedResponse(message: error.toString()));
218	    } catch (error) {
219	      // Any other thrown platform exception (e.g. the plugin's channel
220	      // itself failing) must never escape unmapped either (RNF09) — fail
221	      // closed, same as the documented `LocalAuthException` branch above,
222	      // mirroring `SessionRepositoryImpl.restoreSession()`'s own plain
223	      // `catch`.
224	      return left(Failure.malformedResponse(message: error.toString()));
225	    }
226	  }
227	
228	  @override
229	  Future<Either<Failure, Unit>> submitPin(String pin) async {
230	    final generation = ++_submitPinGeneration;
231	    try {
232	      final storedPin = await _secureStorage.read(key: _pinStorageKey);
233	      if (generation != _submitPinGeneration) {
234	        // A newer `submitPin` call started while this one was still
235	        // awaiting `read` (e.g. the caller's own UI timed out and the user
236	        // retried) — never let this superseded attempt write a possibly
237	        // stale PIN or emit `unlocked` behind the newer attempt's back.
238	        return left(
239	          const Failure.malformedResponse(
240	            message: 'Superseded by a newer PIN attempt',
241	          ),
242	        );
243	      }
244	      // No PIN-creation screen exists anywhere in `docs/input/` (Design
245	      // Notes) — the first ever `submitPin` call sets the stored PIN
246	      // instead of comparing against one.
247	      if (storedPin == null) {
248	        await _secureStorage.write(key: _pinStorageKey, value: pin);
249	        _emit(VaultStatus.unlocked);
250	        return right(unit);
251	      }
252	      if (storedPin == pin) {
253	        _emit(VaultStatus.unlocked);
254	        return right(unit);
255	      }
256	      // Mismatch — status stays `locked`, no attempt cap (Boundaries: "PIN
257	      // has no attempt cap — always retryable"); never `Failure.authInvalid`
258	      // (reserved for password login), same rationale as `authenticate()`.
259	      return left(
260	        const Failure.malformedResponse(
261	          message: 'PIN did not match the stored PIN',
262	        ),
263	      );
264	    } catch (error) {
265	      // A thrown platform exception from the secure-storage channel must
266	      // never escape unmapped either (RNF09) — fail closed, same as
267	      // `authenticate()`'s own plain `catch`.
268	      return left(Failure.malformedResponse(message: error.toString()));
269	    }
270	  }
271	
272	  @override
273	  Future<void> dispose() async {
274	    WidgetsBinding.instance.removeObserver(this);
275	    await _statusController.close();
276	  }
277	}
