1	import 'package:fpdart/fpdart.dart';
2	
3	import '../../../../core/failure/failure.dart';
4	import '../../../../core/network/api_client.dart';
5	import '../models/auth_response_dto.dart';
6	
7	/// The two write calls (`auth-signup`, `auth-login`) — exactly `{email,
8	/// password}`, no extra field (epics.md Story 1.3 AC). Posts via the shared
9	/// `ApiClient` (already anon-keyed for these two functions through
10	/// `HeaderInterceptor.anonKeyOnlyFunctions`, AD-5).
11	class AuthRemoteDataSource {
12	  AuthRemoteDataSource(this._apiClient);
13	
14	  final ApiClient _apiClient;
15	
16	  Future<Either<Failure, AuthResponseDto>> signUp({
17	    required String email,
18	    required String password,
19	  }) => _post('auth-signup', email: email, password: password);
20	
21	  Future<Either<Failure, AuthResponseDto>> logIn({
22	    required String email,
23	    required String password,
24	  }) => _post('auth-login', email: email, password: password);
25	
26	  /// `auth-refresh` (`openapi.yaml:179-240`) — own body shape (`{refreshToken}`,
27	  /// no `email`/`password`) and own response shape (`{data: {session}}`,
28	  /// no `user`), so it can't reuse [_post]/[AuthResponseDto]. Decodes the
29	  /// nested `session` object straight into [AuthSessionDto] (Code Map: reuse
30	  /// as-is, no DTO change).
31	  Future<Either<Failure, AuthSessionDto>> refresh(String refreshToken) async {
32	    final result = await _apiClient.post(
33	      'auth-refresh',
34	      data: {'refreshToken': refreshToken},
35	    );
36	    return result.flatMap((json) {
37	      try {
38	        final data = json['data'] as Map<String, dynamic>;
39	        final session = data['session'] as Map<String, dynamic>;
40	        return right(AuthSessionDto.fromJson(session));
41	      } catch (error) {
42	        // A 200 response that doesn't match the expected shape is a
43	        // client-side parse failure, never a backend-sent code — maps to
44	        // the local-only `malformedResponse` (RNF09: no exception escapes).
45	        return left(Failure.malformedResponse(message: error.toString()));
46	      }
47	    });
48	  }
49	
50	  Future<Either<Failure, AuthResponseDto>> _post(
51	    String function, {
52	    required String email,
53	    required String password,
54	  }) async {
55	    final result = await _apiClient.post(
56	      function,
57	      data: {'email': email, 'password': password},
58	    );
59	    return result.flatMap((json) {
60	      try {
61	        return right(AuthResponseDto.fromJson(json));
62	      } catch (error) {
63	        // A 200 response that doesn't match the expected shape is a
64	        // client-side parse failure, never a backend-sent code — maps to
65	        // the local-only `malformedResponse` (RNF09: no exception escapes).
66	        return left(Failure.malformedResponse(message: error.toString()));
67	      }
68	    });
69	  }
70	}
