8	import 'core/failure/failure.dart';
9	import 'core/navigation/app_router.dart';
10	import 'core/navigation/expiry_overlay_host.dart';
11	import 'features/auth/domain/repositories/session_repository.dart';
12	import 'features/vault/domain/repositories/vault_repository.dart';
13	
14	Future<void> main() async {
15	  WidgetsFlutterBinding.ensureInitialized();
16	  try {
17	    await setupCoreDependencies();
18	  } catch (error) {
19	    debugPrint(
20	      'Cerne failed to start: could not load .env ($error). Copy '
21	      '.env.example to .env and fill in FUNCTIONS_BASE_URL + '
22	      'SUPABASE_ANON_KEY before running the app.',
23	    );
24	    rethrow;
25	  }
26	  runApp(const CerneApp());
27	}
