14	/// Same shape as `app_router_test.dart`'s own `_FakeVaultRepository` — a
15	/// plain fake (not mocktail) so `authenticate()`'s resolution can be held
16	/// open with a `Completer`, which this suite needs to observe the screen's
17	/// mid-flight state, plus a scriptable `submitPin()` for the PIN-flow
18	/// cases (spec-2-2).
19	class _FakeVaultRepository implements VaultRepository {
20	  VaultStatus _status = VaultStatus.locked;
21	  final _controller = StreamController<VaultStatus>.broadcast();
22	
23	  /// Controls what the NEXT `authenticate()` call resolves to. Defaults to
24	  /// `false` (a quiet decline), matching `app_router_test.dart`'s own
25	  /// default so a bare `pumpWidget` never silently unlocks.
26	  bool authenticateSucceeds = false;
27	
28	  /// The `Failure.message` the next failing `authenticate()` call
29	  /// returns — lets a test simulate a distinctly-flavored failure (e.g.
30	  /// an OS-lockout code) while still exercising the real production
31	  /// behavior, which maps every `LocalAuthException`/`false` result to
32	  /// the same generic `Failure.malformedResponse` with no code-specific
33	  /// branch (review finding: proves the "same routing regardless of
34	  /// flavor" claim instead of only asserting it by comment).
35	  String authenticateFailureMessage = 'fake: biometrics declined';
36	
37	  /// Lets a test hold `authenticate()` unresolved to inspect a mid-flight
38	  /// frame before letting it settle.
39	  Completer<void>? authenticateGate;
40	
41	  int authenticateCallCount = 0;
42	
43	  /// The one PIN `submitPin()` treats as "stored" — `null` means no PIN
44	  /// has been stored yet, matching `VaultRepositoryImpl`'s own set-on-
45	  /// first-use behavior (spec-2-2 Design Notes).
46	  String? storedPin;
47	
48	  int submitPinCallCount = 0;
49	
50	  /// Lets a test hold `submitPin()` unresolved — mirrors
51	  /// [authenticateGate]'s own rationale, used to prove `VaultLockScreen`'s
52	  /// re-entrancy guard against a fast second PIN entry firing a second
53	  /// concurrent call.
54	  Completer<void>? submitPinGate;
55	
56	  @override
57	  VaultStatus get currentStatus => _status;
58	
59	  @override
60	  Stream<VaultStatus> get statusStream => _controller.stream;
61	
62	  @override
63	  Future<Either<Failure, Unit>> authenticate() async {
64	    authenticateCallCount += 1;
65	    final gate = authenticateGate;
66	    if (gate != null) {
67	      await gate.future;
68	    }
69	    if (authenticateSucceeds) {
70	      _status = VaultStatus.unlocked;
71	      _controller.add(_status);
72	      return right(unit);
73	    }
74	    return left(Failure.malformedResponse(message: authenticateFailureMessage));
75	  }
76	
77	  @override
78	  Future<Either<Failure, Unit>> submitPin(String pin) async {
79	    submitPinCallCount += 1;
80	    final gate = submitPinGate;
81	    if (gate != null) {
82	      await gate.future;
83	    }
84	    if (storedPin == null) {
85	      storedPin = pin;
86	      _status = VaultStatus.unlocked;
87	      _controller.add(_status);
88	      return right(unit);
89	    }
90	    if (storedPin == pin) {
91	      _status = VaultStatus.unlocked;
92	      _controller.add(_status);
93	      return right(unit);
94	    }
95	    return left(
96	      const Failure.malformedResponse(message: 'fake: PIN mismatch'),
97	    );
98	  }
99	
100	  @override
101	  Future<void> dispose() => _controller.close();
102	}
103	
104	Widget _wrap(VaultRepository vaultRepository) {
105	  return MaterialApp(
106	    home: VaultLockScreen(vaultRepository: vaultRepository),
107	  );
108	}
