110	Future<void> _enterPin(WidgetTester tester, String pin) async {
111	  for (final digit in pin.split('')) {
112	    await tester.tap(find.text(digit));
113	    await tester.pump();
114	  }
115	  // Auto-advance fires 350ms after the 4th digit (UX-DR14).
116	  await tester.pump(const Duration(milliseconds: 350));
117	}
