510	        fakeVaultRepository.submitPinGate = Completer<void>();
511	        final announcements = interceptAnnouncements(tester);
512	
513	        await tester.pumpWidget(_wrap(fakeVaultRepository));
514	        await tester.pumpAndSettle();
515	
516	        await _enterPin(tester, '1234');
517	        await tester.pump(const Duration(seconds: 10, milliseconds: 1));
518	
519	        expect(
520	          announcements,
521	          contains('Não foi possível verificar o PIN. Tente novamente.'),
522	        );
523	
524	        fakeVaultRepository.submitPinGate!.complete();
525	        await tester.pumpAndSettle();
526	      },
527	    );
