14	Map<String, dynamic> _refreshBody({
15	  String accessToken = 'new-access-token',
16	  String refreshToken = 'new-refresh-token',
17	}) => {
18	  'data': {
19	    'session': {
20	      'accessToken': accessToken,
21	      'refreshToken': refreshToken,
22	      'expiresIn': 3600,
23	      'expiresAt': 1999999999,
24	      'tokenType': 'bearer',
25	    },
26	  },
27	};
