29	void main() {
30	  late MockApiClient mockApiClient;
31	  late AuthRemoteDataSource dataSource;
32	
33	  setUp(() {
34	    mockApiClient = MockApiClient();
35	    dataSource = AuthRemoteDataSource(mockApiClient);
36	  });
37	
38	  // RNF09 — this story's slice of the 15-scenario matrix is `auth-refresh`,
39	  // 3 failure types.
40	  runWriteFailureMatrix<AuthSessionDto>(
41	    endpointName: 'auth-refresh',
42	    stubNetworkTimeout: () =>
43	        when(() => mockApiClient.post(any(), data: any(named: 'data')))
44	            .thenAnswer(
45	              (_) async =>
46	                  left(const Failure.networkTimeout(message: 'Timed out')),
47	            ),
48	    stubMalformedResponse: () =>
49	        when(() => mockApiClient.post(any(), data: any(named: 'data')))
50	            .thenAnswer((_) async => right({'unexpected': 'shape'})),
51	    stubNoConnection: () =>
52	        when(() => mockApiClient.post(any(), data: any(named: 'data')))
53	            .thenAnswer(
54	              (_) async =>
55	                  left(const Failure.networkOffline(message: 'Offline')),
56	            ),
57	    invoke: () => dataSource.refresh('some-refresh-token'),
58	  );
59	
60	  group('AuthRemoteDataSource.refresh', () {
61	    test('posts exactly {refreshToken} to auth-refresh', () async {
62	      when(() => mockApiClient.post('auth-refresh', data: any(named: 'data')))
63	          .thenAnswer((_) async => right(_refreshBody()));
64	
65	      await dataSource.refresh('stored-refresh-token');
66	
67	      final captured = verify(
68	        () =>
69	            mockApiClient.post('auth-refresh', data: captureAny(named: 'data')),
70	      ).captured;
71	      expect(captured.single, {'refreshToken': 'stored-refresh-token'});
72	    });
73	
74	    test('decodes the nested session object into AuthSessionDto', () async {
