16	
17	/// Collects every state the cubit emits for the duration of [act], since the
18	/// stack has no `bloc_test` pin — this drives [AuthCubit] through its public
19	/// API only (never the `@protected` `emit`), the same way any other
20	/// `flutter_bloc` consumer would.
21	Future<List<AuthState>> _emittedDuring(
22	  AuthCubit cubit,
23	  Future<void> Function() act,
24	) async {
25	  final emitted = <AuthState>[];
26	  final subscription = cubit.stream.listen(emitted.add);
27	  await act();
28	  // `submit()`'s awaited repository call resolves its mocked Future on a
29	  // microtask; `Future.delayed(Duration.zero)` only resumes once the whole
30	  // microtask queue (including the stream's event dispatch to our
31	  // listener) has drained, so this reliably waits for every emit `act()`
32	  // triggered before we stop listening.
33	  await Future<void>.delayed(Duration.zero);
34	  await subscription.cancel();
35	  return emitted;
36	}
