59	/// A plain (non-mocktail) fake for [VaultRepository], same rationale as
60	/// [_FakeSessionRepository] above. [authenticateSucceeds] defaults to
61	/// `false` so mounting `VaultLockScreen` — which auto-calls [authenticate]
62	/// once in `initState` — never silently unlocks the vault on its own;
63	/// [setStatus] stays the single, explicit way a test flips vault state.
64	class _FakeVaultRepository implements VaultRepository {
65	  _FakeVaultRepository({VaultStatus initialStatus = VaultStatus.unlocked})
66	    : _status = initialStatus;
67	
68	  VaultStatus _status;
69	  final _controller = StreamController<VaultStatus>.broadcast();
70	  bool authenticateSucceeds = false;
71	
72	  /// The one PIN `submitPin()` treats as "stored" (spec-2-2) — `null`
73	  /// means no PIN has been stored yet, mirroring `VaultRepositoryImpl`'s
74	  /// own set-on-first-use behavior.
75	  String? storedPin;
76	
77	  @override
78	  VaultStatus get currentStatus => _status;
79	
80	  @override
81	  Stream<VaultStatus> get statusStream => _controller.stream;
82	
83	  @override
84	  Future<Either<Failure, Unit>> authenticate() async {
85	    if (authenticateSucceeds) {
86	      setStatus(VaultStatus.unlocked);
87	      return right(unit);
88	    }
89	    return left(
90	      const Failure.malformedResponse(message: 'fake: biometrics declined'),
91	    );
92	  }
93	
94	  @override
95	  Future<Either<Failure, Unit>> submitPin(String pin) async {
96	    if (storedPin == null || storedPin == pin) {
97	      storedPin = pin;
98	      setStatus(VaultStatus.unlocked);
99	      return right(unit);
100	    }
101	    return left(const Failure.malformedResponse(message: 'fake: PIN mismatch'));
102	  }
103	
104	  @override
105	  Future<void> dispose() => _controller.close();
106	
107	  void setStatus(VaultStatus status) {
108	    _status = status;
109	    _controller.add(status);
110	  }
111	}
