15	Future<void> main() async {
16	  WidgetsFlutterBinding.ensureInitialized();
17	  try {
18	    await setupCoreDependencies();
19	  } catch (error) {
20	    debugPrint(
21	      'Cerne failed to start: could not load .env ($error). Copy '
22	      '.env.example to .env and fill in FUNCTIONS_BASE_URL + '
23	      'SUPABASE_ANON_KEY before running the app.',
